let currentLanguage = "en";
let activePage = null;
const languageButton = document.querySelector(".language-toggle");
const themeButton = document.querySelector(".theme-toggle");
const menuButton = document.querySelector(".mobile-menu-button");
const nav = document.querySelector(".primary-nav");
const searchDialog = document.querySelector(".search-dialog");
const searchInput = document.querySelector("#site-search");
const searchResults = document.querySelector("#search-results");
let currentTheme = "light";

function readPreference(key, fallback) {
  try { return localStorage.getItem(key) || fallback; }
  catch { return fallback; }
}

function applyTheme(theme, persist = true) {
  currentTheme = theme === "dark" ? "dark" : "light";
  document.body.dataset.theme = currentTheme;
  document.querySelector('meta[name="theme-color"]').setAttribute("content", currentTheme === "dark" ? "#121d18" : "#173a2d");
  themeButton.setAttribute("aria-pressed", String(currentTheme === "dark"));
  themeButton.querySelector(".theme-icon").textContent = currentTheme === "dark" ? "☼" : "☾";
  const nextThemeIsDark = currentTheme === "light";
  themeButton.querySelector(".theme-label").textContent = translations[currentLanguage][nextThemeIsDark ? "themeLabel" : "themeLightLabel"];
  themeButton.setAttribute("aria-label", translations[currentLanguage][nextThemeIsDark ? "themeAria" : "themeLightAria"]);
  if (persist) {
    try { localStorage.setItem("site-theme", currentTheme); } catch { /* Preferences are optional in restricted browser contexts. */ }
  }
}

function applyLanguage(language) {
  currentLanguage = language === "te" ? "te" : "en";
  document.documentElement.lang = currentLanguage;
  document.body.classList.toggle("lang-te", currentLanguage === "te");
  document.querySelector('meta[name="description"]').setAttribute("content", translations[currentLanguage].metaDescription);
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    if (translations[currentLanguage][key]) element.textContent = translations[currentLanguage][key];
  });
  document.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    const key = element.dataset.i18nAria;
    if (translations[currentLanguage][key]) element.setAttribute("aria-label", translations[currentLanguage][key]);
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    const key = element.dataset.i18nPlaceholder;
    if (translations[currentLanguage][key]) element.setAttribute("placeholder", translations[currentLanguage][key]);
  });
  document.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    const key = element.dataset.i18nAlt;
    if (translations[currentLanguage][key]) element.setAttribute("alt", translations[currentLanguage][key]);
  });
  languageButton.setAttribute("aria-pressed", String(currentLanguage === "te"));
  updateDate(currentLanguage);
  applyTheme(currentTheme, false);
  window.refreshAccountLink?.();
  if (window.updateHeroCarouselLanguage) window.updateHeroCarouselLanguage(currentLanguage);
  updateSearch(searchInput.value);
  if (activePage) renderRoute(activePage, { scroll: false, updateHistory: false });
  try { localStorage.setItem("site-language", currentLanguage); } catch { /* Preferences are optional in restricted browser contexts. */ }
}

window.refreshAccountLink = function () {
  const link = document.querySelector(".account-link");
  if (!link) return;
  let signedIn = false;
  try { signedIn = Boolean(sessionStorage.getItem("peetham-active-email") || localStorage.getItem("peetham-active-email")); }
  catch { signedIn = false; }
  const key = signedIn ? "myAccountLabel" : "accountLabel";
  const ariaKey = signedIn ? "myAccountAria" : "accountAria";
  link.href = `?page=${signedIn ? "account" : "login"}`;
  link.dataset.page = signedIn ? "account" : "login";
  link.setAttribute("aria-label", translations[currentLanguage][ariaKey]);
  const label = link.querySelector("span");
  if (label) label.textContent = translations[currentLanguage][key];
};

function updateDate(language) {
  const locale = language === "te" ? "te-IN" : "en-IN";
  const formatted = new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  document.querySelector("#today-date").textContent = formatted.format(new Date());
}

function updateSearch(query = "") {
  const value = query.trim();
  const defaultKinds = {
    en: { pravachanalu: "Teaching", stotras: "Stotra", dharma: "Dharma topic", books: "Book", calendar: "Event", about: "About", announcements: "Update" },
    te: { pravachanalu: "బోధన", stotras: "స్తోత్రం", dharma: "ధర్మ విషయం", books: "గ్రంథం", calendar: "కార్యక్రమం", about: "పరిచయం", announcements: "వార్త" }
  };
  const matches = value
    ? window.searchSiteContent(value, currentLanguage, 18)
    : ["pravachanalu", "stotras", "dharma", "books", "calendar", "about", "announcements"].map((slug) => {
      const page = window.SITE_PAGES[slug];
      return { slug, titleText: page.title[currentLanguage] || page.title.en, descriptionText: page.subtitle[currentLanguage] || page.subtitle.en, kindText: defaultKinds[currentLanguage][slug], href: `?page=${slug}` };
    });
  if (!matches.length) {
    searchResults.innerHTML = `<p class="search-empty">${translations[currentLanguage].searchEmpty}</p>`;
    return;
  }
  searchResults.innerHTML = matches.map((item) => `<a class="search-result" href="${item.href}" data-page="${item.slug}"${item.start ? ` data-calendar-date="${escapeMarkup(item.start)}"` : ""}><span class="search-result-copy"><small class="search-result-type">${escapeMarkup(item.kindText || "")}</small><strong>${escapeMarkup(item.titleText)}</strong><small class="search-result-description">${escapeMarkup(item.descriptionText)}</small></span><span aria-hidden="true">↗</span></a>`).join("");
}

function escapeMarkup(value) {
  return String(value ?? "").replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]);
}

function renderRoute(slug, { scroll = true, updateHistory = false, calendarDate = null } = {}) {
  activePage = slug || null;
  if (activePage === "calendar") {
    const requestedDate = calendarDate || new URLSearchParams(location.search).get("date");
    if (/^\d{4}-\d{2}-\d{2}$/.test(requestedDate || "")) {
      const parsedDate = new Date(`${requestedDate}T12:00:00`);
      if (!Number.isNaN(parsedDate.getTime())) {
        window.calendarSelectedDate = requestedDate;
        window.calendarViewDate = new Date(parsedDate.getFullYear(), parsedDate.getMonth(), 1, 12);
      }
    }
  }
  const homeView = document.querySelector("#home-view");
  const pageView = document.querySelector("#page-view");
  if (!activePage) {
    homeView.hidden = false;
    pageView.hidden = true;
    pageView.innerHTML = "";
    document.title = translations[currentLanguage].homeTitle;
    if (updateHistory) {
      try { history.pushState({}, "", location.pathname); }
      catch { window.location.href = location.pathname; }
    }
  } else {
    homeView.hidden = true;
    pageView.hidden = false;
    pageView.innerHTML = window.renderSitePage(activePage, currentLanguage);
    window.wirePageInteractions(pageView, currentLanguage);
    const page = window.SITE_PAGES[activePage];
    document.title = `${page?.title?.[currentLanguage] || page?.title?.en || translations[currentLanguage].brandName} — ${translations[currentLanguage].brandName}`;
    if (updateHistory) {
      const dateQuery = activePage === "calendar" && window.calendarSelectedDate ? `&date=${encodeURIComponent(window.calendarSelectedDate)}` : "";
      const destination = `?page=${encodeURIComponent(activePage)}${dateQuery}`;
      try { history.pushState({ page: activePage }, "", destination); }
      catch { window.location.href = destination; }
    }
  }
  document.querySelectorAll("[data-page]").forEach((link) => {
    if (link.closest(".primary-nav")) {
      if (link.dataset.page === activePage) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    }
  });
  if (scroll) window.scrollTo({ top: 0, behavior: "smooth" });
}

document.addEventListener("click", (event) => {
  const link = event.target.closest("a[data-page], a[data-home-link]");
  if (!link || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || link.target === "_blank") return;
  event.preventDefault();
  const slug = link.dataset.page || null;
  renderRoute(slug, { updateHistory: true, calendarDate: link.dataset.calendarDate || null });
  if (searchDialog.open) searchDialog.close();
  nav.classList.remove("is-open");
  menuButton.setAttribute("aria-expanded", "false");
  menuButton.setAttribute("aria-label", translations[currentLanguage].menuOpen);
});

window.addEventListener("popstate", () => {
  renderRoute(new URLSearchParams(location.search).get("page"), { scroll: true, updateHistory: false });
});

languageButton.addEventListener("click", () => applyLanguage(currentLanguage === "en" ? "te" : "en"));
themeButton.addEventListener("click", () => applyTheme(currentTheme === "light" ? "dark" : "light"));
menuButton.addEventListener("click", () => {
  const open = menuButton.getAttribute("aria-expanded") !== "true";
  menuButton.setAttribute("aria-expanded", String(open));
  menuButton.setAttribute("aria-label", open ? translations[currentLanguage].menuClose : translations[currentLanguage].menuOpen);
  nav.classList.toggle("is-open", open);
});
nav.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => {
  nav.classList.remove("is-open");
  menuButton.setAttribute("aria-expanded", "false");
  menuButton.setAttribute("aria-label", translations[currentLanguage].menuOpen);
}));

document.querySelectorAll(".search-open").forEach((button) => button.addEventListener("click", () => {
  searchDialog.showModal();
  updateSearch("");
  window.setTimeout(() => searchInput.focus(), 30);
}));
document.querySelector(".dialog-close").addEventListener("click", () => searchDialog.close());
searchDialog.addEventListener("click", (event) => { if (event.target === searchDialog) searchDialog.close(); });
searchInput.addEventListener("input", () => updateSearch(searchInput.value));
searchInput.addEventListener("keydown", (event) => {
  if (event.key !== "Enter") return;
  const firstResult = searchResults.querySelector("a.search-result");
  if (!firstResult) return;
  event.preventDefault();
  firstResult.click();
});
document.addEventListener("keydown", (event) => {
  if (event.key === "/" && !searchDialog.open && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) {
    event.preventDefault();
    searchDialog.showModal();
    updateSearch("");
    window.setTimeout(() => searchInput.focus(), 30);
  }
});

